# What a backend returns after a message leaves Chatwoot. `message_id` is the provider id
# the echo will carry: pre-generated by us when the backend accepts a caller-supplied id,
# assigned by the provider otherwise.
class Whatsapp::Session::Model::SendResult < Data.define(:message_id, :timestamp, :client_ref)
  include Whatsapp::Session::Model::Serializable
end
